        $verified=DSA\Backup\Portable_Archive_Container::verify($stream,$phrase,$budget);fclose($stream);$stream=null;$actual=[];foreach($verified['inventory']['files']as$row)$actual[$row['path']]=['bytes'=>$row['bytes'],'sha256'=>$row['sha256']];ksort($actual,SORT_STRING);$check($actual===$pair,'all encrypted previous-code members independently authenticate');
        $wrongKeyRefused=false;$stream=fopen($private.'/previous-kiwe.kiwefiles','rb');try{DSA\Backup\Portable_Archive_Container::verify($stream,bin2hex(random_bytes(32)),$budget);}catch(DSA\Backup\Archive_Error $error){$wrongKeyRefused=true;}finally{fclose($stream);$stream=null;}$check($wrongKeyRefused,'wrong previous-code recovery key refuses');
