        $proof['privateMembers']=[];foreach(['previous-kiwe.kiwefiles','previous-kiwe-manifest.json','operator-key.sealed']as$n)$proof['privateMembers'][$n]=['bytes'=>filesize($private.'/'.$n),'sha256'=>hash_file('sha256',$private.'/'.$n)];$proof['fullSiteBackup']=false;$proof['kiweSettingsCaptured']=false;$proof['offlineCopyCompleted']=false;$proof['originalBinaryPairAuthenticated']=true;$proof['passed']=true;$proof['milliseconds']=(hrtime(true)-$started)/1000000;
